n,producer_session_id,expires_at,created_at,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?)',(pid,b.family_id,b.run_id,b.run_class,b.digest,bj,ctx.session_id,str(payload['expires_at']),now,rph));c.execute(\"INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)\",(pid,'NONE','PROPOSED',now,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':'PROPOSED','seq':ctx.ledger_sequence}),rph));c.execute('COMMIT')\n  except BaseException:\n   if not c.getautocommit():c.execute('ROLLBACK')\n   raise\n  finally:c.close()\n  return {'status':'PASS','proposal_id':pid,'state':'PROPOSED','binding_sha256':b.digest}\n def transition(self,pid:str,target:str,ctx:DaemonContext,observed_binding_sha256:str|None=None)->dict[str,Any]:\n  c=self._open()\n  try:\n   row=c.execute('SELECT binding_sha256,producer_session_id,expires_at,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?',(pid,)).fetchone()\n   if not row:raise FailClosed('PROPOSAL_NOT_FOUND')\n   last=c.execute('SELECT transition_id,to_state,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1',(pid,)).fetchone();current=last[1]\n   wanted={'PROPOSED':'PRECONDITIONS_PASS','PRECONDITIONS_PASS':'HUMAN_OWNER_SIGNED','HUMAN_OWNER_SIGNED':'APPLIED'}.get(current)\n   if target!=wanted:raise FailClosed('ILLEGAL_AUTHORITY_TRANSITION')\n   if target=='PRECONDITIONS_PASS' and observed_binding_sha256!=row[0]:raise FailClosed('BINDING_MISMATCH')\n   if target in {'HUMAN_OWNER_SIGNED','APPLIED'}:\n    if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')\n    if ctx.session_id==row[1]:raise FailClosed('OWNER_SESSION_SEPARATION_FAILED')\n   c.execute('BEGIN IMMEDIATE');c.execute(\"INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)\",(pid,current,target,ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':target,'seq':ctx.ledger_sequence}),row[3]));c.execute('COMMIT')\n  except BaseException:\n   if not c.getautocommit():c.execute('ROLLBACK')\n   raise\n  finally:c.close()\n  return {'status':'PASS','proposal_id':pid,'state':target}\n def register_delegation(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:\n  d=OwnerConditionalDelegation(**payload);v=DelegationVerifier(_owner_key());v.verify_signature(d);sig=__import__('base64').b64decode(d.owner_signature)\n  c=self._open()\n  rph=resource_policy_sha256(d.resource_policy)\n  c=self._open()\n  try:\n   # Amendment C and D must already have been directly owner-applied before\n   # the dormant root credential can enter production.\n   observed=[x[0] for x in c.execute('SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal')]\n   if observed[:2]!=['C','D']:raise FailClosed('C_AND_D_DIRECT_OWNER_APPLIED_REQUIRED')\n   c.execute('INSERT INTO owner_conditional_delegations(delegation_id,owner_identity,owner_credential_scheme,unsigned_payload_json,owner_signature_b64,owner_signature_sha256,owner_session_id,expires_at,scope_sha256,state,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(d.delegation_id,d.owner_identity,d.owner_credential_scheme,canonical_json(d.unsigned_payload()),d.owner_signature,hashlib.sha256(sig).hexdigest(),d.owner_session_id,d.expires_at,d.scope_hash,'ACTIVE',rph))\n  finally:c.close()\n  return {'status':'PASS','delegation_id':d.delegation_id,'scope_sha256':d.scope_hash}\n def redeem(self,delegation_id:str,proposal_payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:\n  c=self._open()\n  try:\n   r=c.execute('SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?',(delegation_id,)).fetch