peer_uid,_sha(event),event.get('resource_policy_sha256')));tid=c.last_insert_rowid();c.execute('INSERT INTO delegation_redemptions(redemption_event_id,delegation_id,child_proposal_id,preconditions_transition_id,human_owner_signed_transition_id,scope_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?)',(event['redemption_event_id'],delegation_id,p.proposal_id,pre[0],tid,event['scope_hash'],event.get('resource_policy_sha256')));c.execute('COMMIT')\n  except BaseException:\n   if not c.getautocommit():c.execute('ROLLBACK')\n   raise\n  finally:c.close()\n  return {'status':'PASS','event':event}\n def revoke(self,delegation_id:str,ctx:DaemonContext)->dict[str,Any]:\n  if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')\n  eid='revoke-'+_sha({'d':delegation_id,'seq':ctx.ledger_sequence})[:32];c=self._open()\n  try:c.execute('INSERT INTO owner_delegation_revocations VALUES(?,?,?,?,?)',(eid,delegation_id,ctx.recorded_at,ctx.ledger_sequence,ctx.peer_uid))\n  finally:c.close()\n  return {'status':'PASS','event':'OWNER_DELEGATION_REVOKED','revocation_event_id':eid}\n def register_amendment(self,delegation_id:str,amendment_id:str,amendment_hash:str,ctx:DaemonContext)->dict[str,Any]:\n  c=self._open()\n  try:\n   r=c.execute('SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?',(delegation_id,)).fetchone()\n   if not r:raise FailClosed('DELEGATION_NOT_FOUND')\n   if c.execute('SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?',(delegation_id,)).fetchone():raise FailClosed('DELEGATION_REVOKED')\n   dd=json.loads(r[0]);dd['owner_signature']=r[1];d=OwnerConditionalDelegation(**dd);v=DelegationVerifier(_owner_key());v.verify_signature(d)\n   observed=[x[0] for x in c.execute('SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal')]\n   if observed[:2]!=['C','D'] or amendment_id not in {'A','B'}:raise FailClosed('C_D_A_B_ORDER_VIOLATION')\n   expected=['C','D','A','