121665*pow(121666,_Q-2,_Q))%_Q\n_I=pow(2,(_Q-1)//4,_Q)\n_IDENTITY=(0,1)\ndef _xrecover(y:int,sign:int)->int:\n    xx=((y*y-1)*pow((_D*y*y+1)%_Q,_Q-2,_Q))%_Q\n    x=pow(xx,(_Q+3)//8,_Q)\n    if (x*x-xx)%_Q:x=(x*_I)%_Q\n    if (x*x-xx)%_Q:raise ValueError('point is not on curve')\n    if (x&1)!=sign:x=_Q-x\n    return x\ndef _decode_point(raw:bytes)->tuple[int,int]:\n    if len(raw)!=32:raise ValueError('encoded point length')\n    n=int.from_bytes(raw,'little');sign=n>>255;y=n&((1<<255)-1)\n    if y>=_Q:raise ValueError('noncanonical point')\n    p=(_xrecover(y,sign),y)\n    if _encode_point(p)!=raw:raise ValueError('noncanonical point encoding')\n    return p\ndef _encode_point(p:tuple[int,int])->bytes:\n    x,y=p;return (y|((x&1)<<255)).to_bytes(32,'little')\ndef _add(p:tuple[int,int],q:tuple[int,int])->tuple[int,int]:\n    x1,y1=p;x2,y2=q;t=(_D*x1*x2*y1*y2)%_Q\n    return (((x1*y2+x2*y1)*pow((1+t)%_Q,_Q-2,_Q))%_Q,\n            ((y1*y2+x1*x2)*pow((1-t)%_Q,_Q-2,_Q))%_Q)\ndef _mul(p:tuple[int,int],n:int)->tuple[int,int]:\n    out=_IDENTITY;cur=p\n    while n:\n        if n&1:out=_add(out,cur)\n        cur=_add(cur,cur);n>>=1\n    return out\n_BY=(4*pow(5,_Q-2,_Q))%_Q\n_B=(_xrecover(_BY,0),_BY)\ndef verify_ed25519(public_key:bytes,message:bytes,signature:bytes)->None:\n    if len(public_key)!=32 or len(signature)!=64:raise ValueError('Ed25519 length')\n    a=_decode_point(public_key);rraw=signature[:32];r=_decode_point(rraw)\n    s=int.from_bytes(signature[32:],'little')\n    if s>=_L:raise ValueError('noncanonical scalar')\n    if _mul(a,8)==_IDENTITY or _mul(r,8)==_IDENTITY:raise ValueError('small-order point')\n    h=int.from_bytes(hashlib.sha512(rraw+public_key+message).digest(),'little')%_L\n    if _encode_point(_mul(_B,s))!=_encode_point(_add(r,_mul(a,h))):\n        raise ValueError('invalid Ed25519 signature')\n\ndef _utc(x:str)->datetime:\n    if not x.endswith('Z'):raise AuthorityError('UTC timestamp required')\n    return datetime.fromisoformat(x[:-1]+'+00:00').astimezone(timezone.utc)\n\n@dataclass(frozen=True)\nclass OwnerConditionalDelegation:\n    delegation_id:str; owner_identity:str; owner_credential_scheme:str\n    issued_at_verified_external_time:str; expires_at:str; owner_session_id:str\n    allowed_campaign:str; allowed_family:str; allowed_run_classes:tuple[str,...]\n    allowed_evidence_domains:tuple[str,...]; allowed_scientific_root_hashes:tuple[str,...]\n    allowed_amendment_hashes:tuple[str,...]; allowed_dataset_manifest_hash:str\n    allowed_revision_hash:str; allowed_pit_rule_hash:str; allowed_candidate_list_hash:str\n    allowed_candidate_grammar_hash:str; allowed_enumerator_hash:str\n    allowed_evaluation_order_hash:str; allowed_scientific_contract_hash:str\n    allowed_evaluator_hash:str\n    allowed_t1_prereg_hash:str; allowed_integrity_void_contract_hash:str\n    allowed_child_authority_types:tuple[str,...]; allowed_information_domains:tuple[str,...]\n    explicit_prohibitions:tuple[str,...]; expiry_policy:str; revocation_state:str\n    parent_delegation_nonce:str; resource_policy:dict[str,Any]\n    amendment_a_sha256:str; amendment_b_sha256:str\n    amendment_d_sha256:str; amendment_c_sha256:str\n    owner_signature:str=''\n\n    def unsigned_payload(self)->dict[str,Any]:\n        d=asdict(self);d.pop('owner_signature');return d\n    @property\n    def scope_hash(self)->str:return hashlib.sha256(canonical_json(self.unsigned_payload())).hexdigest()\n\n@dataclass(frozen=True)\nclass ChildProposal:\n    proposal_id:str; proposal_type:str; producer_session_id:str; campaign:str\n    family:str; run_class:str; evidence_domain:str; scientific_root_hash:str\n    amendment_hash:str|None; dataset_manifest_hash:str; revision_hash:str\n    pit_rule_hash:str; candidate_list_hash:str; candidate_grammar_hash:str\n    enumerator_hash:str; evaluation_order_hash:str; scientific_contract_hash:str\n    t1_prereg_hash:str; integrity_void_contract_hash:str; evaluator_hash:str\n    evaluator_registered:bool; twenty_ob