E:\codex-LOOP\codex-loop-s-f2\data\reports\headless-wave\adhoc-c98ffa1069-root-after-d-gate\adhoc-c98ffa1069-root-after-d-gate-19e8c8cfda8a4d1a8fe521e91aae953d\events.jsonl:47:{"type":"item.completed","item":{"id":"item_22","type":"command_execution","command":"\"C:\\\\WINDOWS\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\powershell.exe\" -Command \"Get-Content E:\\\\VPS\\\\direct_repair_stage\\\\authority_store.py -Raw\"","aggregated_output":"\"\"\"Daemon-only PC7 authority persistence backed by append-only schema v2.\"\"\"\nfrom __future__ import annotations\nimport hashlib,json,os\nfrom dataclasses import replace\nfrom pathlib import Path\nfrom typing import Any\nimport apsw\ntry:\n from .research_db import FailClosed, canonical_json\n from .conditional_delegation import (OwnerConditionalDelegation,ChildProposal,\n     DelegationVerifier)\n from .authority_runtime import (DaemonContext,FrozenBindings,resource_policy_sha256)\nexcept ImportError:\n from research_db import FailClosed, canonical_json\n from conditional_delegation import (OwnerConditionalDelegation,ChildProposal,\n     DelegationVerifier)\n from authority_runtime import (DaemonContext,FrozenBindings,resource_policy_sha256)\n\ndef _sha(x:Any)->str:return hashlib.sha256(canonical_json(x).encode()).hexdigest()\ndef _owner_key()->bytes:\n    p=os.environ.get('P5_OWNER_ED25519_PUBLIC_KEY_FILE','')\n    if not p or not Path(p).is_file():raise FailClosed('OWNER_PUBLIC_KEY_NOT_CONFIGURED')\n    b=Path(p).read_bytes()\n    if len(b)!=32:raise FailClosed('OWNER_PUBLIC_KEY_INVALID')\n    return b\ndef _owner_uid()->int:return int(os.environ.get('P5_OWNER_PEER_UID','-1'))\nAMENDMENT_C_SHA256='5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83'\ndef _amendment_d_sha256()->str:\n h=os.environ.get('P5_AMENDMENT_D_SHA256','')\n if len(h)!=64 or any(x not in '0123456789abcdef' for x in h):raise FailClosed('AMENDMENT_D_HASH_NOT_PINNED')\n return h\ndef _expected_amendment_hash(amendment_id:str)->str:\n if amendment_id=='C':return AMENDMENT_C_SHA256\n if amendment_id=='D':return _amendment_d_sha256()\n key='P5_AMENDMENT_'+amendment_id+'_SHA256'\n h=os.environ.get(key,'')\n if len(h)!=64 or any(x not in '0123456789abcdef' for x in h):raise FailClosed(key+'_NOT_PINNED')\n return h\n\nclass AuthorityStore:\n def __init__(self,db_path:Path):self.db_path=db_path\n def _open(self):\n  c=apsw.Connection(str(self.db_path));c.set_busy_timeout(2000);c.execute('PRAGMA foreign_keys=ON');return c\n def proposal(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:\n  b=FrozenBindings(**payload['bindings']).validate();pid=str(payload['proposal_id']);bj=canonical_json(vars(b));now=ctx.recorded_at\n  rph=resource_policy_sha256(b.resource_scope) if b.wave_id is not None else None\n  c=self._open()\n  try:\n   c.execute('BEGIN IMMEDIATE');c.execute('INSERT INTO authority_proposals(proposal_id,family_id,run_id,run_class,binding_sha256,binding_json,producer_session_id,expires_at,created_at,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?)',(pid,b.family_id,b.run_id,b.run_class,b.digest,bj,ctx.session_id,str(payload['expires_at']),now,rph));c.execute(\"INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)\",(pid,'NONE','PROPOSED',now,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':'PROPOSED','seq':ctx.ledger_sequence}),rph));c.execute('COMMIT')\n  except BaseException:\n   if not c.getautocommit():c.execute('ROLLBACK')\n   raise\n  finally:c.close()\n  return {'status':'PASS','proposal_id':pid,'state':'PROPOSED','binding_sha256':b.digest}\n def transition(self,pid:str,target:str,ctx:DaemonContext,observed_binding_sha256:str|None=None)->dict[str,Any]:\n  c=self._open()\n  try:\n   row=c.execute('SELECT binding_sha256,producer_session_id,expires_at,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?',(pid,)).fetchone()\n   if not row:raise FailClosed('PROPOSAL_NOT_FOUND')\n   last=c.execute('SELECT transition_id,to_state,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1',(pid,)).fetchone();current=last[1]\n   wanted={'PROPOSED':'PRECONDITIONS_PASS','PRECONDITIONS_PASS':'HUMAN_OWNER_SIGNED','HUMAN_OWNER_SIGNED':'APPLIED'}.get(current)\n   if target!=wanted:raise FailClosed('ILLEGAL_AUTHORITY_TRANSITION')\n   if target=='PRECONDITIONS_PASS' and observed_binding_sha256!=row[0]:raise FailClosed('BINDING_MISMATCH')\n   if target in {'HUMAN_OWNER_SIGNED','APPLIED'}:\n    if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')\n    if ctx.session_id==row[1]:raise FailClosed('OWNER_SESSION_SEPARATION_FAILED')\n   c.execute('BEGIN IMMEDIATE');c.execute(\"INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)\",(pid,current,target,ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':target,'seq':ctx.ledger_sequence}),row[3]));c.execute('COMMIT')\n  except BaseException:\n   if not c.getautocommit():c.execute('ROLLBACK')\n   raise\n  finally:c.close()\n  return {'status':'PASS','proposal_id':pid,'state':target}\n def register_delegation(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:\n  d=OwnerConditionalDelegation(**payload);v=DelegationVerifier(_owner_key());v.verify_signature(d);sig=__import__('base64').b64decode(d.owner_signature)\n  rph=resource_policy_sha256(d.resource_policy)\n  c=self._open()\n  try:\n   # Amendment C and D must already have been directly owner-applied before\n   # the dormant root credential can enter production.\n   observed=list(c.execute('SELECT amendment_id,amendment_sha256 FROM amendment_registrations ORDER BY registration_ordinal'))\n   expected=[('C',d.a